//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

/// Clones share the same scores, so each match thread keeps its own handle.
#[derive(Clone, Default)]
pub struct Board {
    scores: Arc<Mutex<ScoreState>>,
}

#[derive(Default)]
struct ScoreState {
    players: HashMap<PlayerId, i64>,
    total: i64,
}

#[cfg(test)]
mod regression_tests {
    use super::Board;
    use std::sync::{mpsc, Arc, Barrier};
    use std::thread;
    use std::time::Duration;

    #[test]
    fn rejoining_replaces_score_in_total() {
        let board = Board::new();
        board.join(1, 10);
        board.join(1, 3);
        assert_eq!((board.score(1), board.total()), (3, 3));
    }

    #[test]
    fn self_transfer_completes_without_changing_scores() {
        let board = Board::new();
        board.join(1, 10);
        let (finished, completion) = mpsc::channel();
        thread::spawn(move || {
            board.transfer(1, 1, 7);
            finished.send((board.score(1), board.total())).unwrap();
        });
        assert_eq!(
            completion.recv_timeout(Duration::from_secs(2)).unwrap(),
            (10, 10)
        );
    }

    #[test]
    fn concurrent_awards_and_opposing_transfers_preserve_points() {
        let board = Board::new();
        board.join(1, 0);
        board.join(2, 0);
        let start = Arc::new(Barrier::new(4));
        let (finished, completion) = mpsc::channel();
        for worker in 0..4 {
            let board = board.clone();
            let start = start.clone();
            let finished = finished.clone();
            thread::spawn(move || {
                start.wait();
                for _ in 0..10_000 {
                    board.award(1, 1);
                    if worker % 2 == 0 {
                        board.transfer(1, 2, 1);
                    } else {
                        board.transfer(2, 1, 1);
                    }
                }
                finished.send(()).unwrap();
            });
        }
        drop(finished);
        for _ in 0..4 {
            completion.recv_timeout(Duration::from_secs(10)).unwrap();
        }
        assert_eq!(
            (board.score(1), board.score(2), board.total()),
            (40_000, 0, 40_000)
        );
    }
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn join(&self, id: PlayerId, score: i64) {
        let mut scores = self.scores.lock().unwrap();
        let previous = scores.players.insert(id, score).unwrap_or(0);
        scores.total = (i128::from(scores.total) - i128::from(previous) + i128::from(score))
            .try_into()
            .expect("replacement total must fit i64");
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let mut scores = self.scores.lock().unwrap();
        let score = scores.players[&id] + points;
        let total = scores.total + points;
        scores.players.insert(id, score);
        scores.total = total;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        let mut scores = self.scores.lock().unwrap();
        let from_score = scores.players[&from];
        let to_score = scores.players[&to];
        if from == to {
            return;
        }
        let from_score = from_score - points;
        let to_score = to_score + points;
        scores.players.insert(from, from_score);
        scores.players.insert(to, to_score);
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        self.scores.lock().unwrap().players[&id]
    }

    pub fn total(&self) -> i64 {
        self.scores.lock().unwrap().total
    }
}
